@@ -0,0 +1,93 @@
+package cache
+
+import (
+	"errors"
+	"testing"
+	"time"
+)
+
+func TestSimpleCache(t *testing.T) {
+	c := NewSimpleCache[string]()
+	if err := c.Add("plain", "value"); err != nil {
+		t.Fatal(err)
+	}
+	if got, err := c.Get("plain"); err != nil || got != "value" {
+		t.Fatalf("Get plain = %q, %v", got, err)
+	}
+	if err := c.AddWithTTL("short", "temporary", 20*time.Millisecond); err != nil {
+		t.Fatal(err)
+	}
+	if got, err := c.Get("short"); err != nil || got != "temporary" {
+		t.Fatalf("Get before expiry = %q, %v", got, err)
+	}
+	deadline := time.Now().Add(time.Second)
+	for {
+		got, err := c.Get("short")
+		if err != nil {
+			if got != "" {
+				t.Fatalf("expired value = %q", got)
+			}
+			break
+		}
+		if time.Now().After(deadline) {
+			t.Fatal("entry did not expire")
+		}
+		time.Sleep(time.Millisecond)
+	}
+	for _, key := range c.Keys() {
+		if key == "short" {
+			t.Fatal("expired key returned by Keys")
+		}
+	}
+	if got, err := c.Get("missing"); err == nil || got != "" {
+		t.Fatalf("missing value = %q, %v", got, err)
+	}
+}
+
+func TestSimpleCacheLoader(t *testing.T) {
+	c := NewSimpleCache[int]()
+	calls := 0
+	loader := func(key string) (int, time.Duration, error) {
+		calls++
+		return 42, time.Hour, nil
+	}
+	for i := 0; i < 2; i++ {
+		if got, err := c.GetWithLoader("loaded", loader); err != nil || got != 42 {
+			t.Fatalf("GetWithLoader = %d, %v", got, err)
+		}
+	}
+	if calls != 1 {
+		t.Fatalf("loader called %d times", calls)
+	}
+	want := errors.New("load failed")
+	if got, err := c.GetWithLoader("failed", func(string) (int, time.Duration, error) {
+		return 99, time.Hour, want
+	}); got != 0 || err != want {
+		t.Fatalf("failed loader = %d, %v", got, err)
+	}
+	if got, err := c.Get("failed"); got != 0 || err == nil {
+		t.Fatalf("failed key stored: %d, %v", got, err)
+	}
+	if got, err := c.GetWithLoader("short", func(string) (int, time.Duration, error) {
+		calls++
+		return calls, 20 * time.Millisecond, nil
+	}); err != nil || got != 2 {
+		t.Fatalf("first short load = %d, %v", got, err)
+	}
+	deadline := time.Now().Add(time.Second)
+	for {
+		if _, err := c.Get("short"); err != nil {
+			break
+		}
+		if time.Now().After(deadline) {
+			t.Fatal("loaded entry did not expire")
+		}
+		time.Sleep(time.Millisecond)
+	}
+	if got, err := c.GetWithLoader("short", func(string) (int, time.Duration, error) {
+		calls++
+		return calls, time.Hour, nil
+	}); err != nil || got != 3 {
+		t.Fatalf("reload after TTL = %d, %v", got, err)
+	}
+}

