+func TestSimpleCache(t *testing.T) {
+	c := NewSimpleCache[string]()
+	if err := c.Add("plain", "value"); err != nil {
+		t.Fatal(err)
+	}
+	if got, err := c.Get("plain"); err != nil || got != "value" {
+		t.Fatalf("Get plain = %q, %v", got, err)
+	}
+	if err := c.AddWithTTL("short", "temporary", 20*time.Millisecond); err != nil {
+		t.Fatal(err)
+	}
+	if got, err := c.Get("short"); err != nil || got != "temporary" {
+		t.Fatalf("Get before expiry = %q, %v", got, err)
+	}
+	deadline := time.Now().Add(time.Second)
+	for {
+		got, err := c.Get("short")
+		if err != nil {
+			if got != "" {
+				t.Fatalf("expired value = %q", got)
+			}
+			break
+		}
+		if time.Now().After(deadline) {
+			t.Fatal("entry did not expire")
+		}
+		time.Sleep(time.Millisecond)
+	}
+	for _, key := range c.Keys() {
+		if key == "short" {
+			t.Fatal("expired key returned by Keys")
+		}
+	}
+	if got, err := c.Get("missing"); err == nil || got != "" {
+		t.Fatalf("missing value = %q, %v", got, err)
+	}
